def _recommended_seed_block(existing: list[int], *, target: int, use_case_index: int) -> list[int]:
    seen = {int(seed) for seed in existing}
    seed = (use_case_index + 1) * 1000
    out: list[int] = []
    while len(out) < max(0, int(target)) and seed < 1_000_000:
        if seed not in seen:
            out.append(seed)
        seed += 1
    return out


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _git_branch(repo: Path) -> str:
    try:
        out = subprocess.check_output(
            ["git", "-C", str(repo), "branch", "--show-current"],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
        return out or "unknown"
    except Exception:
        return "unknown"


def _json_load(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def _json_dump(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def _jsonl_load(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not path.is_file():
        return rows
    for raw in path.read_text(encoding="utf-8").splitlines():
        if not raw.strip():
            continue
        try:
            payload = json.loads(raw)
        except Exception:
            continue
        if isinstance(payload, dict):
            rows.append(payload)
    return rows


def _run_eval_once(
    *,
    provider: str,
    model: str,
    project_id: str,
    repeat: int,
    seed_start: int,
    max_steps: int,
    task_concurrency: int,
    result_path: Path,
    trace_dir: Path,
    task_cache: str | None,
    include_reasoning: bool,
    use_site_knowledge: bool,
    use_local_html_context: bool,
    failure_judge: bool,
    temperature: float,
    use_case: str | None,
    eval_timeout_seconds: int | None,
) -> list[str]:
    cmd = [
        sys.executable,
        str(ROOT / "eval.py"),
        "--provider",
        provider,
        "--model",
        model,
        "--web-project-id",
        project_id,
        "--repeat",
        str(max(1, int(repeat))),
        "--seed",
        str(int(seed_start)),
        "--max-steps",
        str(max(1, int(max_steps))),
        "--task-concurrency",
        str(max(1, int(task_concurrency))),
        "--temperature",
        str(float(temperature)),
        "--save-act-traces",
        "--trace-dir",
        str(trace_dir),
        "--out",
        str(result_path),
    ]
    if use_case:
        cmd.extend(["--use-case", str(use_case)])
        cmd.extend(["--num-tasks", "1"])
    else:
        cmd.extend(["--all-use-cases", "--tasks-per-use-case", "1"])
    if include_reasoning:
        cmd.append("--include-reasoning")
    if use_site_knowledge:
        cmd.append("--use-site-knowledge")
    if use_local_html_context:
        cmd.append("--use-local-html-context")
    if not failure_judge:
        cmd.append("--no-failure-judge")
    if task_cache:
        cmd.extend(["--task-cache", str(task_cache)])
    print(f"[harvest] running eval: {' '.join(cmd)}")
    subprocess.run(
        cmd,
        check=True,
        cwd=str(ROOT),
        timeout=(None if not eval_timeout_seconds else int(eval_timeout_seconds)),
    )
    return [str(part) for part in cmd]


def _failure_category(ep: dict[str, Any], near_miss_threshold: float) -> str:
    if bool(ep.get("success")):
        return "SUCCESS"
    for key in ("judge_failure_category", "failure_category"):
        value = ep.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip().upper()
    score = float(ep.get("score") or 0.0)
    if score >= float(near_miss_threshold):
        return "NEAR_MISS"
    if score <= 0.0:
        return "ZERO_SCORE"
    return "PARTIAL_FAILURE"


def _load_result_paths(glob_patterns: list[str]) -> list[Path]:
    paths: list[Path] = []
    for pattern in glob_patterns:
        if any(ch in pattern for ch in "*?[]"):
            if pattern.startswith("/"):
                matches = sorted(Path(p) for p in glob.glob(pattern))
            else:
                matches = sorted(ROOT.glob(pattern))
            paths.extend(p.resolve() for p in matches if p.is_file())
            continue
        p = Path(pattern)
        if not p.is_absolute():
            p = (ROOT / p).resolve()
        if p.is_file():
            paths.append(p)
    seen: set[str] = set()
    out: list[Path] = []
    for path in paths:
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        out.append(path)
    return out


def _load_trace_roots(glob_patterns: list[str]) -> list[Path]:
    roots: list[Path] = []
    for pattern in glob_patterns:
        if any(ch in pattern for ch in "*?[]"):
            if pattern.startswith("/"):
                matches = sorted(Path(p) for p in glob.glob(pattern))
            else:
                matches = sorted(ROOT.glob(pattern))
            roots.extend(p.resolve() for p in matches if p.is_dir())
            continue
        p = Path(pattern)
        if not p.is_absolute():
            p = (ROOT / p).resolve()
        if p.is_dir():
            roots.append(p)
    seen: set[str] = set()
    out: list[Path] = []
    for root in roots:
        key = str(root)
        if key in seen or not (root / "trace_index.json").is_file():
            continue
        seen.add(key)
        out.append(root)
    return out


def _trace_root_for_result(
    result_path: Path,
    explicit_trace_roots: list[Path],
    episode_task_ids: set[str],
) -> Path | None:
    stem = result_path.stem

    def _root_key(root: Path) -> str:
        key = root.name
        for prefix in ("traces_", "trace_"):
            if key.startswith(prefix):
                key = key[len(prefix) :]
                break
        if key.endswith("_traces"):
            key = key[: -len("_traces")]
        return key

    result_keys = {stem}
    if stem.startswith("eval_"):
        result_keys.add(stem[len("eval_") :])
    valid_roots = [root for root in explicit_trace_roots if (root / "trace_index.json").is_file()]
    if valid_roots:
        matching_roots = []
        for root in valid_roots:
            key = _root_key(root)
            if key in result_keys or any(key.endswith(k) for k in result_keys):
                matching_roots.append(root)
        if len(matching_roots) == 1:
            return matching_roots[0]
        if len(matching_roots) > 1:
            return sorted(
                matching_roots,
                key=lambda r: (r / "trace_index.json").stat().st_mtime,
                reverse=True,
            )[0]

        overlap_matches: list[tuple[int, int, float, Path]] = []
